return {
    msg: {
        error: "Missing fields in message and/or metadata."}, 
        metadata: metadata, 
        msgType: msgType
};

return {
    msg: {
        error: "Not an uplink fPort"
    }, 
    metadata: metadata, 
    msgType: msgType
};

var decoderVersion = null;
if (msg.attributes != null) {
    var attrs = msg.attributes;
    if (attrs.deviceEUI != null) {
        dev = attrs.deviceEUI;
        // make sure it's got 4 symbols.
        if (dev.length() >= 4) {

            if (dev.substring(0, 4) == "AC1F") {
                // RAK radio chip
                decoderVersion = "Gen2";
            } else if (dev.substring(0, 4) ==
                // RN "Microchip" radio chip
                "0004") {
                decoderVersion = "Gen1";
            }
        }
    }
}

if (decoderVersion != null) {
    if (msg.attributes != null) {
        msg.attributes.decoderVersion = decoderVersion;
    } else {
        msg.attributes = {
            decoderVersion: decoderVersion
        };
    }
}

return {
    msg: msg,
    metadata: metadata,
    msgType: msgType
};

return {
    msg: {
        error: "Failed to identify decoder version"
    }, 
    metadata: metadata, 
    msgType: msgType
};

if (msg.attributes != null) {
    var attrs = msg.attributes;
    if (attrs.decoderVersion != null && attrs.decoderVersion == "Gen2") {
        return true;
    }
}
return false;

if (msg.attributes != null) {
    var attrs = msg.attributes;
    if (attrs.decoderVersion != null && attrs.decoderVersion == "Gen1") {
        return true;
    }
}
return false;

