// {"frmPayload": "bxeAAqUtgAAAXf8=", "fPort": 1, "fCnt": 999}
// {"frmPayload": "bz+EDtMd4QEeAf8=", "fPort": 1, "fCnt": 999}

// Utilities by Rytis 2026-04-02

function round0(x) {
    if (x == null) {
        return null;
    }
    return Math.round(x);
}

function round1(x) {
    if (x == null) {
        return null;
    }
    return Math.round(x * 10.0) / 10.0;
}

function round2(x) {
    if (x == null) {
        return null;
    }
    return Math.round(x * 100.0) / 100.0;
}

function error_msg(text) {
    return {
        msg: {
            error: text,
            raw: msg.frmPayload,
            fCnt: msg.fCnt
        },
        metadata: metadata != null ? metadata : {},
        msgType: msgType != null ? msgType : "POST_TELEMETRY_REQUEST"
    };
}

function bytesToBits(bytes) {
    var bits = [];

    for (var i = 0; i < bytes.length; i++) {
        var b = bytes[i];

        // normalize signed → unsigned
        if (b < 0) {
            b += 256;
        }

        // extract bits (MSB → LSB)
        for (var j = 7; j >= 0; j--) {
            bits.push((b >> j) & 1);
        }
    }

    return bits;
}
// Base64 to bits.
function newBitReader(b64) {
    if (b64 == null) {
        return null;
    }

    var raw = base64ToBytesList(b64);
    var bytes = [];
    for (var i = 0; i < raw.length; i++) {
        var b = raw[i];
        if (b < 0) {
            b = b + 256;
        }
        bytes.push(b);
    }

    if (bytes.length == 0) {
        return null;
    }
    var bits = bytesToBits(bytes);

    return {
        repr: bits,
        pos: 0
    };
}

function readBits(br, N) {
    if (br == null) {
        return null;
    }

    if (br.repr == null) {
        return null;
    }

    if (br.pos == null) {
        return null;
    }

    if (N == null || N <= 0) {
        return 0;
    }

    var len = br.repr.length;

    if (br.pos + N > len) {
        return null;
    }

    var value = 0;
    var i = 0;

    while (i < N) {
        var idx = br.pos;

        // safe index check (TBEL defensive)
        if (idx < 0 || idx >= len) {
            return null;
        }

        var bit = br.repr[idx];

        // ensure valid bit
        if (bit == null) {
            return null;
        }

        if (bit != 0 && bit != 1) {
            return null;
        }

        // accumulate (MSB-first)
        value = (value * 2) + bit;

        // advance position
        br.pos = br.pos + 1;
        i = i + 1;
    }

    return value;
}


var br = newBitReader(msg.frmPayload);

if (br == null) {
    return error_msg("invalid_payload");
}
var len = br.repr.length;

var batt = null;
var t = null;
var tm = null;
var tx = null;
var h = null;
var p = null;
var s = null;
var sx = null;
var temp = null;

// 11 byte Payload 11*8 = 88.
if (br.repr.length == 88) {
    temp = readBits(br, 2);
    if (temp != 1) {
        return error_msg("payload_not_type_1");
    }
    temp = readBits(br, 5);
    batt = (temp!=null && temp<parseInt(1<<5) ? round1(3.0 + (0.05 * temp)) : null);
    temp = readBits(br, 11);
    t    = (temp!=null && temp<parseInt(1<<11) ? round1((0.1 * temp) - 100) : null);
    if (t!=null) {
        temp = readBits(br, 6);
        tm   = (temp!=null && temp<parseInt(1<<6) ? round1(t - (0.1 * temp)) : null);
        temp = readBits(br, 6);
        tx   = (temp!=null && temp<parseInt(1<<6) ? round1(t + (0.1 * temp)) : null);
    }
    temp = readBits(br, 9);
    h    = (temp!=null && temp<parseInt(1<<9) ? round1(0.2 * temp) : null);
    temp = readBits(br, 14);
    p    = (temp!=null && temp<parseInt(1<<14) ? round2(500 + (0.05 * temp)) : null);
    temp=readBits(br, 10);
    s    = (temp!=null && temp<parseInt(1<<10) ? 2*temp: null);
    if (s != null) {
        temp = readBits(br, 9);
        sx   = (temp!=null && temp<parseInt(1<<9) ? s + 2*temp: null);
    }
}

return {
    msg: {
        helix_batt: batt, 
        t: t, 
        tm: tm, 
        tx: tx, 
        h: h, 
        p: p, 
        s: s, 
        sx: sx
    },
    metadata: metadata,
    msgType: msgType
};

